import pytest
from PIL import Image as PILImage
from requests import HTTPError
from requests.exceptions import InvalidSchema, RequestException

from saleor.product import ProductMediaTypes
from saleor.product.models import ProductMedia
from saleor.product.tasks import fetch_product_media_image_task


def _valid_jpeg_bytes():
    buf = BytesIO()
    PILImage.new("RGB", (2, 2)).save(buf, format="JPEG")
    return buf.getvalue()


class FakeResponse:
    def __init__(self, status_code=200, content_type="image/jpeg", content=b""):
        self.status_code = status_code
        self.headers = {"content-type": content_type}
        self.content = content


@contextmanager
def _cm(resp):
    yield resp


def _patch_send(resp=None, exc=None):
    if exc is not None:
        return mock.patch(
            "saleor.product.tasks.HTTPClient.send_request", side_effect=exc
        )
    return mock.patch(
        "saleor.product.tasks.HTTPClient.send_request", return_value=_cm(resp)
    )


@pytest.fixture
def media(product):
    return ProductMedia.objects.create(
        product=product,
        external_url="http://example.com/img.jpg",
        type=ProductMediaTypes.IMAGE,
        oembed_data="{}",
    )


def test_success(media, media_root):
    resp = FakeResponse(content=_valid_jpeg_bytes())
    with _patch_send(resp):
        fetch_product_media_image_task(media.pk)
    media.refresh_from_db()
    assert media.image
    assert media.external_url is None


def test_already_has_image(product_media_image):
    with mock.patch("saleor.product.tasks.HTTPClient.send_request") as m:
        fetch_product_media_image_task(product_media_image.pk)
    m.assert_not_called()


def test_missing_record():
    fetch_product_media_image_task(99999)  # no error


def test_no_external_url_no_image(product):
    media = ProductMedia.objects.create(
        product=product, type=ProductMediaTypes.IMAGE, oembed_data="{}"
    )
    fetch_product_media_image_task(media.pk)
    assert ProductMedia.objects.filter(pk=media.pk).exists()


def test_video_type(product):
    media = ProductMedia.objects.create(
        product=product,
        external_url="http://example.com/v",
        type=ProductMediaTypes.VIDEO,
        oembed_data="{}",
    )
    with mock.patch("saleor.product.tasks.HTTPClient.send_request") as m:
        fetch_product_media_image_task(media.pk)
    m.assert_not_called()
    assert not media.refresh_from_db()
    assert ProductMedia.objects.filter(pk=media.pk).exists()


def test_non_image_content_type(media):
    resp = FakeResponse(content_type="text/plain", content=b"hi")
    with _patch_send(resp):
        fetch_product_media_image_task(media.pk)
    assert not ProductMedia.objects.filter(pk=media.pk).exists()


def test_svg_deleted(media):
    resp = FakeResponse(content_type="image/svg+xml", content=b"<svg/>")
    with _patch_send(resp):
        fetch_product_media_image_task(media.pk)
    assert not ProductMedia.objects.filter(pk=media.pk).exists()


@pytest.mark.parametrize("exc", [RequestException(), InvalidSchema()])
def test_transient_reraises_and_survives(media, exc):
    with _patch_send(exc=exc):
        with pytest.raises(RequestException):
            fetch_product_media_image_task(media.pk)
    assert ProductMedia.objects.filter(pk=media.pk).exists()


def test_on_failure_deletes(media):
    fetch_product_media_image_task.on_failure(
        RequestException(), "task-id", [media.pk], {}, None
    )
    assert not ProductMedia.objects.filter(pk=media.pk).exists()


@pytest.mark.parametrize("status", [500, 502, 503])
def test_5xx_retries_keeps_url(media, status):
    resp = FakeResponse(status_code=status)
    with _patch_send(resp):
        with pytest.raises(HTTPError):
            fetch_product_media_image_task(media.pk)
    media.refresh_from_db()
    assert media.external_url == "http://example.com/img.jpg"
    assert ProductMedia.objects.filter(pk=media.pk).exists()


@pytest.mark.parametrize("status", [100, 199, 300, 301, 401, 404, 499])
def test_non_5xx_errors_delete(media, status):
    resp = FakeResponse(status_code=status)
    with _patch_send(resp):
        fetch_product_media_image_task(media.pk)
    assert not ProductMedia.objects.filter(pk=media.pk).exists()


def test_invalid_image_deleted(media):
    resp = FakeResponse(content=b"not-an-image")
    with mock.patch(
        "saleor.product.utils.tasks_utils.Image.open", side_effect=SyntaxError("bad")
    ):
        with _patch_send(resp):
            fetch_product_media_image_task(media.pk)
    assert not ProductMedia.objects.filter(pk=media.pk).exists()
